#!/usr/bin/env python3
"""ด่าน — ทุก `D<n>` ที่ถูกอ้างถึง ต้องมีนิยามอยู่ใน docs/engine/README.md

ใช้:  .github/check-decision-refs.py <README.md> <ไฟล์.md> [...]
คืน:  0 = ทุกการอ้างอิงมีปลายทาง · 1 = มี `D<n>` ที่ชี้ไปที่ที่ไม่มีอยู่

╔══════════════════════════════════════════════════════════════════════════╗
║ 🔴 ขอบเขตของด่านนี้ — อ่านก่อนนับว่ามันครอบคลุมอะไร                        ║
║                                                                          ║
║ มันจับได้อย่างเดียวคือ **"อ้างถึง `D` ที่ไม่มีอยู่"**                        ║
║ 🔴 **มันจับ "กล่องที่ค้างเป็นเท็จ" ไม่ได้เลยแม้แต่นิดเดียว**                  ║
║    — ซึ่งคือปัญหาจริงที่ทำให้เรื่องนี้ถูกยกขึ้นมา (`D71` · 25 ส.ค. 2026)      ║
║    กล่อง "ยังไม่มีคำตอบ" ใน column-map.md ค้างเป็นเท็จ 1 วันเต็ม            ║
║    หลัง `D53`–`D56` ตอบไปแล้ว → P1 อ่าน เชื่อ แล้วตัดสินซ้ำ                ║
║    **การตัดสินซ้ำคือวิธีผลิต `P-51`** (สองมติที่ถูกทั้งคู่ตอนเขียน ขัดกันเอง)  ║
║                                                                          ║
║ ⚠️ **ห้ามให้ด่านนี้ไปนั่งแทนที่ของจริงในความรู้สึกว่าเรื่องนี้ถูกจัดการแล้ว**    ║
║    ของจริงต้องรอทะเบียนคำถาม (`Q<n>`) ที่ P8 กำลังออกแบบ                   ║
║    เพราะระบบ `D` ออกเลขให้ **คำตอบ** เท่านั้น                              ║
║    **คำถามที่ยังเปิดจึงไม่มีที่อยู่ที่เป็นทางการเลยสักที่** — นั่นคือรากของปัญหา ║
║    พอมี `Q<n>` แล้ว ด่านที่ตรวจ "กล่องเปิดที่ถูกตอบไปแล้ว" จะเขียนได้ทันที    ║
╚══════════════════════════════════════════════════════════════════════════╝

🔴 นิยามนับเฉพาะ **หัวข้อ** (`### D53 — …`) กับ **แถวตาราง** (`| D22 | … |`) ใน README
   ไม่นับการอ้างถึงในเนื้อความ — ไม่งั้นการพิมพ์ `D99` ผิดในย่อหน้าเดียว
   จะกลายเป็น "นิยาม" ของตัวเอง แล้วด่านก็ผ่านตัวเองเงียบๆ
"""
import re
import sys

# รองรับเลขทศนิยมด้วย (`D3.1` มีอยู่จริงในเอกสาร)
HEAD_RE = re.compile(r"^#{1,6}[^\n]*?\bD(\d+(?:\.\d+)?)\b", re.M)
ROW_RE = re.compile(r"^\|\s*`?D(\d+(?:\.\d+)?)`?\s*\|", re.M)
REF_RE = re.compile(r"`D(\d+(?:\.\d+)?)`")


def main(argv) -> int:
    if len(argv) < 2:
        print("ใช้: check-decision-refs.py <README.md> <ไฟล์...>")
        return 1
    readme, paths = argv[0], argv[1:]
    try:
        text = open(readme, encoding="utf-8").read()
    except OSError:
        print(f"🔴 decision-refs: เปิด {readme} ไม่ได้ — ตรวจไม่ได้ ถือว่าไม่ผ่าน")
        return 1
    defined = set(HEAD_RE.findall(text)) | set(ROW_RE.findall(text))

    bodies = {}
    for path in paths:
        try:
            bodies[path] = open(path, encoding="utf-8").read()
        except OSError:
            continue
    any_ref = any(REF_RE.search(b) for b in bodies.values())

    # 🔴 "README ไม่มีนิยามเลย" เป็นเรื่องผิดปกติ **ก็ต่อเมื่อมีคนอ้างถึง `D` อยู่จริง**
    #    ถ้าไม่มีใครอ้างถึงเลย ก็ไม่มีอะไรให้ตรวจ — ไม่ใช่ความผิด
    #    (เดิมเขียนให้ fail เสมอ แล้วมันไปฟ้องทรีที่ README ยังไม่มีมติสักข้อ ซึ่งถูกต้องตามสภาพ)
    if any_ref and not defined:
        print(f"🔴 decision-refs: มีการอ้างถึง `D` แต่ {readme} ไม่มีนิยามสักตัว — ผิดปกติ ถือว่าไม่ผ่าน")
        return 1
    if not any_ref:
        return 0

    bad = 0
    for path, body in bodies.items():
        for d in sorted(set(REF_RE.findall(body)) - defined, key=lambda x: float(x)):
            print(f"🔴 decision-refs: {path} อ้างถึง `D{d}` ซึ่งไม่มีนิยามใน {readme}")
            bad += 1
    if bad:
        print(f"   เพิ่มหัวข้อ `### D{'<n>'} — …` ใน README หรือแก้เลขที่อ้างให้ถูก")
        return 1
    print(f"✅ decision-refs: ทุก `D<n>` ที่อ้างถึง มีนิยามครบ (นิยาม {len(defined)} ตัว)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
